def _farkas_core(prob):
    At = (prob.A.T).tocsr()
    blocks = [At]
    if prob.K:
        blocks.append(prob.E.T.tocsr())
    return sparse.hstack(blocks, format="csr")


def solve_infeasible(prob):
    """Return (y, q): a normalized Farkas witness for the canonical LP.

    Primary strategy minimises the infinity norm of (y, q) subject to the
    homogeneous dual cone and the b^T y + d^T q = 1 normalisation, which keeps
    the certificate small and therefore numerically robust.  A margin
    maximisation variant is kept as a fallback.
    """
    R = prob.R
    K = prob.K
    n = prob.n
    core = _farkas_core(prob)
    rhs = np.concatenate([prob.b, prob.d]) if (K or True) else None

    candidates = []

    # ---- strategy 1: minimum infinity-norm certificate -------------------
    nc = R + K + 1
    top = sparse.hstack([core, sparse.csr_matrix((n, 1))], format="csr")
    yrows = sparse.hstack(
        [-sparse.eye(R, format="csr"), sparse.csr_matrix((R, K)),
         -sparse.csr_matrix(np.ones((R, 1)))], format="csr")
    if K:
        qrows = sparse.hstack(
            [sparse.csr_matrix((2 * K, R)),
             sparse.vstack([sparse.eye(K), -sparse.eye(K)], format="csr"),
             -sparse.csr_matrix(np.ones((2 * K, 1)))], format="csr")
        loosen = sparse.vstack([yrows, qrows], format="csr")
    else:
        loosen = yrows
    M_ub = sparse.vstack([top, loosen], format="csr")
    b_ub = np.zeros(n + R + 2 * K)
    A_eq = sparse.csr_matrix(np.concatenate([prob.b, prob.d, [0.0]])[None, :])
    bounds = [(None, 0.0)] * R + [(None, None)] * K + [(0.0, 1.0e7)]
    obj = np.zeros(nc)
    obj[-1] = 1.0
    for method, opts in (("highs", {}), ("highs", {"presolve": False}),
                         ("highs-ds", {"presolve": False})):
        try:
            res = linprog(obj, A_ub=M_ub, b_ub=b_ub, A_eq=A_eq, b_eq=[1.0],
                          bounds=bounds, method=method, options=opts)
        except Exception as exc:            # pragma: no cover - safety net
            sys.stderr.write("farkas norm attempt failed: %r\n" % (exc,))
            continue
        if res.status == 0 and res.x is not None:
            z = np.array(res.x, dtype=float)
            candidates.append((z[:R].copy(), z[R:R + K].copy()))
            break

    # ---- strategy 2: margin maximisation ---------------------------------
    for box in (1.0e6, 1.0e7):
        M_ub2 = sparse.hstack([core, sparse.csr_matrix(np.ones((n, 1)))],
                              format="csr")
        b_ub2 = np.zeros(n)
        A_eq2 = sparse.csr_matrix(
            np.concatenate([prob.b, prob.d, [0.0]])[None, :])
        bounds2 = [(-box, 0.0)] * R + [(-box, box)] * K + [(0.0, 1.0)]
        obj2 = np.zeros(R + K + 1)
        obj2[-1] = -1.0
        for method, opts in (("highs", {}), ("highs", {"presolve": False})):
            try:
                res = linprog(obj2, A_ub=M_ub2, b_ub=b_ub2, A_eq=A_eq2,
                              b_eq=[1.0], bounds=bounds2, method=method,
                              options=opts)
            except Exception as exc:        # pragma: no cover - safety net
                sys.stderr.write("farkas margin attempt failed: %r\n" % (exc,))
                continue
            if res.status == 0 and res.x is not None:
                z = np.array(res.x, dtype=float)
                candidates.append((z[:R].copy(), z[R:R + K].copy()))
                break

    best = None
    for y, q in candidates:
        val = float(prob.b.dot(y))
        if K:
            val += float(prob.d.dot(q))
        if not np.isfinite(val) or val <= 0.0:
            continue
        if abs(val - 1.0) > 1e-9:
            y = y / val
            q = q / val
        col = _dense_cols(prob, y, q)
        worst_col = float(np.max(col))
        worst_y = float(np.max(y)) if y.size else 0.0
        err = abs(float(prob.b.dot(y)) +
                  (float(prob.d.dot(q)) if K else 0.0) - 1.0)
        score = max(worst_col, worst_y, err)
        if not np.isfinite(score):
            continue
        cand = (score, float(np.max(np.abs(np.concatenate([y, q]))))
                if (y.size + q.size) else 0.0, y, q)
        if best is None or (cand[0], cand[1]) < (best[0], best[1]):
            best = cand
    if best is None:
        return None, None
    return best[2], best[3]


# --------------------------------------------------------------------------
# response assembly
# --------------------------------------------------------------------------

def _num(v):
    v = float(v)
    if not np.isfinite(v):
        return 0.0
    if v == 0.0:
        return 0.0
    return v


def response_optimal(prob, epoch, x, y, q, mlu, migration, loads):
    flows = []
    idx = 0
    for paths in prob.paths:
        row = []
        for _ in paths:
            row.append(_num(x[idx]))
            idx += 1
        flows.append(row)
    return {
        "epoch": epoch,
        "status": "optimal",
        "flows": flows,
        "loads": [_num(v) for v in loads],
        "mlu": _num(mlu),
        "migration": _num(migration),
        "dual": {
            "inequality": [_num(v) for v in y],
            "equality": [_num(v) for v in q],
        },
    }


def response_infeasible(epoch, y, q):
    return {
        "epoch": epoch,
        "status": "infeasible",
        "certificate": {
            "inequality": [_num(v) for v in y],
            "equality": [_num(v) for v in q],
        },
    }


def handle(req):
    prob = Problem(req)
    sol = solve_optimal(prob)
    if sol is not None:
        x, y, q = sol
        x, t, loads, mlu, migration = primal_from_flows(prob, x)
        eq_res, ineq_res = primal_residuals(prob, x, t, mlu)
        if eq_res <= 1e-6 and ineq_res <= 1e-6:
            col, ymax, dl = dual_quality(prob, y, q, mlu)
            if col <= 1e-8 and ymax <= 1e-8 and dl <= 1e-7:
                return response_optimal(prob, req["epoch"], x, y, q, mlu,
                                        migration, loads)
            y2, q2 = solve_dual_lp(prob)
            col2, ymax2, dl2 = dual_quality(prob, y2, q2, mlu)
            if y2 is not None and (col2, ymax2, dl2) < (col, ymax, dl) \
                    and col2 <= 1e-7 and ymax2 <= 1e-7 and dl2 <= 2e-5:
                y, q = y2, q2
            return response_optimal(prob, req["epoch"], x, y, q, mlu,
                                    migration, loads)
    y, q = solve_infeasible(prob)
    if y is None:
        # last resort: report the numerical trouble rather than crash.
        sys.stderr.write("certificate failure\n")
        return {"status": "invalid"}
    return response_infeasible(req["epoch"], y, q)


# --------------------------------------------------------------------------
# line protocol
# --------------------------------------------------------------------------

def iter_lines(fd):
    cur = bytearray()
    over = False
    while True:
        try:
            chunk = os.read(fd, 1 << 16)
        except InterruptedError:            # pragma: no cover
            continue
        except OSError:                     # pragma: no cover
            break
        if not chunk:
            break
        pos = 0
        size = len(chunk)
        while pos < size:
            idx = chunk.find(b"\n", pos)
            if idx < 0:
                if not over:
                    cur += chunk[pos:]
                    if len(cur) + 1 > MAX_LINE:
                        over = True
                        del cur[:]
                pos = size
            else:
                if over:
                    over = False
                    yield None
                else:
                    cur += chunk[pos:idx]
                    if len(cur) + 1 > MAX_LINE:
                        yield None
                    else:
                        yield bytes(cur)
                    del cur[:]
                pos = idx + 1
    if over:
        yield None
    elif cur:
        yield bytes(cur) if len(cur) <= MAX_LINE else None


def main():
    out = sys.stdout
    for payload in iter_lines(0):
        if payload is None:
            resp = {"status": "invalid"}
        else:
            try:
                req = parse_request(payload)
                resp = handle(req)
            except Invalid:
                resp = {"status": "invalid"}
            except Exception as exc:        # pragma: no cover - safety net
                sys.stderr.write("request failed: %r\n" % (exc,))
                resp = {"status": "invalid"}
        out.write(json.dumps(resp, allow_nan=False))
        out.write("\n")
        out.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())

