"""Large parallel campaign across all generators."""
import json, sys, time, importlib
from multiprocessing import Pool
sys.path.insert(0,'/app/work')

def worker(task):
    seed, kind, prog = task
    import gen as G, gen2 as G2, maxsize as MS, longpath as LP, check as C
    if kind == "rand": r = G.gen(seed)
    elif kind == "feas": r = G2.gen(seed, budget_mode="auto")
    elif kind == "tight": r = G2.gen(seed, budget_mode="huge", tight=1.0)
    elif kind == "exact": r = G2.gen(seed, budget_mode="exact", tight=1.05)
    elif kind == "maxsize": r = MS.gen(seed)
    elif kind == "long": r = LP.gen(seed)
    data = (json.dumps(r)+"\n").encode()
    import subprocess
    p = subprocess.run([sys.executable, prog], input=data, capture_output=True, timeout=600)
    if p.returncode != 0:
        return (seed, kind, "CRASH rc=%d" % p.returncode, p.stderr.decode()[-500:])
    try:
        resp = json.loads(p.stdout.decode())
    except Exception as e:
        return (seed, kind, "BAD OUTPUT", p.stdout.decode()[:200])
    L = C.build(r)
    try:
        st, val = C.check_response(r, resp, L)
        return (seed, kind, None, st)
    except Exception as e:
        return (seed, kind, repr(e), json.dumps(resp)[:300] + " REQ " + json.dumps(r)[:300])

def main():
    n = int(sys.argv[1]); seed0 = int(sys.argv[2])
    prog = sys.argv[3] if len(sys.argv) > 3 else '/app/submission/planner.py'
    kinds = ["rand", "feas", "tight", "exact", "maxsize", "long"]
    tasks = [(seed0 + i, kinds[i % len(kinds)], prog) for i in range(n)]
    t0 = time.time()
    from collections import Counter
    c = Counter(); bad = 0
    with Pool(4) as pool:
        for seed, kind, err, info in pool.imap_unordered(worker, tasks, chunksize=2):
            if err:
                bad += 1
                print("FAIL", kind, seed, err)
                print("   ", info[:600])
            else:
                c[(kind, info)] += 1
    print("done %d tasks in %.1fs, bad %d" % (n, time.time()-t0, bad))
    for k in sorted(c): print("   ", k, c[k])
    return 1 if bad else 0

sys.exit(main())
