    res = []
    if len(out) != len(reqs):
        return [(seeds[0], kind, "LINE COUNT %d vs %d" % (len(out), len(reqs)), "")]
    for s, r, line in zip(seeds, reqs, out):
        try:
            resp = json.loads(line)
